void Editor::smokeTextRasterization(){smoke_=true;homeOpen_=false;documentOpen_=true;pending_=Pending::None;document=Document(32,32);refresh();useTextTool();auto data=newTextToolData(0xff113355);data.text=u"MoonSprite 文字😀";data.boxed=true;data.originX=2;data.originY=3;data.boxWidth=20;data.boxHeight=16;const auto history=document.historySize();SetEnvironmentVariableW(L"MOONSPRITE_TEXT_RASTER_SMOKE",L"1");try{editText(data,{},false);}catch(...){SetEnvironmentVariableW(L"MOONSPRITE_TEXT_RASTER_SMOKE",nullptr);throw;}SetEnvironmentVariableW(L"MOONSPRITE_TEXT_RASTER_SMOKE",nullptr);if(document.textDraftActive()||document.timeline().state().layers.size()!=2||!document.layer().kind.empty()||document.cel().text||document.historySize()!=history+2)throw std::runtime_error("Text dialog stale cancellation restored converted draft");const auto layer=document.layer().id;document.undo();if(document.layer().kind!="text"||!document.cel().text)throw std::runtime_error("Text conversion menu undo failed");document.redo();if(document.layer().id!=layer||!document.layer().kind.empty()||document.cel().text)throw std::runtime_error("Text conversion menu redo failed");document=Document();refresh();}
